<?php
session_start();include('dbstring.php');include('check-login.php');include_once('administration-ops-utils.php');include_once('duty-roster-utils.php');include_once('staff-permission-utils.php');administration_ops_ensure_tables($con);ensure_duty_roster_tables($con);staff_permission_ensure_table($con);if(!administration_ops_is_lead()){header('location:index.php');exit();}
$today=date('Y-m-d');$duty=mysqli_query($con,"SELECT dr.dutytitle,dr.dutylocation,CONCAT_WS(' ',su.firstname,su.othernames,su.surname) staff_name FROM tbldutyroster dr INNER JOIN tblsystemuser su ON su.userid=dr.userid WHERE dr.status='active' AND '$today' BETWEEN dr.startdate AND dr.enddate ORDER BY dr.dutytitle,su.firstname");$permissions=mysqli_query($con,"SELECT r.*,CONCAT_WS(' ',su.firstname,su.othernames,su.surname) staff_name FROM tblstaffpermissionrequest r LEFT JOIN tblsystemuser su ON su.userid=r.requester_id WHERE r.status IN ('pending','approved') AND r.start_datetime < DATE_ADD(NOW(),INTERVAL 1 DAY) AND r.end_datetime >= CURDATE() ORDER BY r.status='pending' DESC,r.start_datetime ASC");$counts=['duty'=>0,'pending'=>0,'away'=>0];$res=mysqli_query($con,"SELECT COUNT(*) total FROM tbldutyroster WHERE status='active' AND '$today' BETWEEN startdate AND enddate");if($res&&($r=mysqli_fetch_assoc($res)))$counts['duty']=(int)$r['total'];$res=mysqli_query($con,"SELECT status,COUNT(*) total FROM tblstaffpermissionrequest WHERE status IN ('pending','approved') AND start_datetime < DATE_ADD(NOW(),INTERVAL 1 DAY) AND end_datetime >= CURDATE() GROUP BY status");if($res)while($r=mysqli_fetch_assoc($res)){if($r['status']==='pending')$counts['pending']=(int)$r['total'];else $counts['away']=(int)$r['total'];}
?>
<!doctype html><html><head><?php include('title.php');include('links.php');?><link rel="stylesheet" href="css/headmaster-dashboard.css"><link rel="stylesheet" href="css/assistant-admin-ops.css"></head><body class="hm-page aops-page"><div class="header"><?php include('menu.php');?></div><main class="hm-shell"><aside class="hm-sidebar"><div class="hm-sidebar__inner"><?php include('welcome.php');include('menuboard.php');?></div></aside><section class="hm-main"><section class="hm-hero hm-hero--single aops-hero"><div><span class="hm-kicker">Staff coordination</span><h1>Staff availability board</h1><p>See who is on duty, permission requests awaiting a decision, and approved staff absences for today.</p><div class="hm-hero__footer"><div class="hm-context"><span><i class="fa fa-calendar"></i> <?php echo date('l, d M Y');?></span><span><i class="fa fa-users"></i> Daily coverage</span></div><a class="aops-back" href="assistant-head-administration-page.php"><i class="fa fa-arrow-left"></i> Dashboard</a></div></div></section><section class="aops-stats"><div class="aops-stat"><i class="fa fa-calendar-check-o"></i><span>Duty assignments today<strong><?php echo number_format($counts['duty']);?></strong></span></div><div class="aops-stat"><i class="fa fa-clock-o"></i><span>Permission requests pending<strong><?php echo number_format($counts['pending']);?></strong></span></div><div class="aops-stat"><i class="fa fa-user-times"></i><span>Approved staff away<strong><?php echo number_format($counts['away']);?></strong></span></div></section><section class="aops-grid"><section class="aops-panel"><div class="hm-panel__head"><div><span class="hm-section__eyebrow">Duty coverage</span><h2>Staff on duty today</h2></div></div><div class="aops-table-wrap"><table class="aops-table"><thead><tr><th>Duty</th><th>Staff member</th></tr></thead><tbody><?php if($duty&&mysqli_num_rows($duty)>0){while($row=mysqli_fetch_assoc($duty)){?><tr><td><strong><?php echo administration_ops_escape($row['dutytitle']);?></strong><small><?php echo administration_ops_escape($row['dutylocation']);?></small></td><td><?php echo administration_ops_escape($row['staff_name']);?></td></tr><?php }}else{?><tr><td colspan="2" class="aops-empty">No active duty entries are scheduled today.</td></tr><?php }?></tbody></table></div></section><section class="aops-panel"><div class="hm-panel__head"><div><span class="hm-section__eyebrow">Absence & permission</span><h2>Staff availability alerts</h2></div><a href="staff-permission-review.php">Review permissions</a></div><div class="aops-table-wrap"><table class="aops-table"><thead><tr><th>Staff member</th><th>Request</th><th>Status</th></tr></thead><tbody><?php if($permissions&&mysqli_num_rows($permissions)>0){while($row=mysqli_fetch_assoc($permissions)){?><tr><td><strong><?php echo administration_ops_escape($row['staff_name']);?></strong></td><td><?php echo administration_ops_escape($row['permission_type']);?><small><?php echo date('d M H:i',strtotime($row['start_datetime']));?> to <?php echo date('d M H:i',strtotime($row['end_datetime']));?></small></td><td><span class="aops-chip<?php echo $row['status']==='pending'?' aops-chip--warn':'';?>"><?php echo administration_ops_escape(ucfirst($row['status']));?></span></td></tr><?php }}else{?><tr><td colspan="3" class="aops-empty">No staff availability alerts for today.</td></tr><?php }?></tbody></table></div></section></section></section></main></body></html>